if ( ! defined( 'ABSPATH' ) ) { exit; } function gc_member_field( $member_id, $key, $fallback = '' ) { $value = get_post_meta( (int) $member_id, $key, true ); return '' !== $value && null !== $value ? $value : $fallback; } function gc_member_public_url( $member_id ) { return home_url( '/community/members/' . sanitize_title( get_the_title( $member_id ) ) . '/' ); } function gc_save_member_v2_fields( $post_id ) { if ( 'gc_member' !== get_post_type( $post_id ) ) { return; } if ( ! isset( $_POST['gc_member_v2_nonce'] ) || ! wp_verify_nonce( $_POST['gc_member_v2_nonce'], 'gc_member_v2_save' ) ) { return; } if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) { return; } if ( ! current_user_can( 'edit_post', $post_id ) ) { return; } $fields = array( 'gc_member_bio' => 'sanitize_textarea_field', 'gc_member_profession' => 'sanitize_text_field', 'gc_member_organisation' => 'sanitize_text_field', 'gc_member_job_title' => 'sanitize_text_field', 'gc_member_skills' => 'sanitize_text_field', 'gc_member_leadership_focus' => 'sanitize_text_field', 'gc_member_chapter_id' => 'absint', 'gc_member_cohort_id' => 'absint', 'gc_member_public_profile' => 'absint', ); foreach ( $fields as $key => $sanitizer ) { if ( isset( $_POST[ $key ] ) ) { update_post_meta( $post_id, $key, call_user_func( $sanitizer, wp_unslash( $_POST[ $key ] ) ) ); } } } add_action( 'save_post_gc_member', 'gc_save_member_v2_fields' ); function gc_member_v2_meta_box() { add_meta_box( 'gc_member_v2_profile', __( 'Game Changer Profile (2.0)', 'game-changers' ), 'gc_member_v2_meta_box_html', 'gc_member', 'normal', 'default' ); } add_action( 'add_meta_boxes', 'gc_member_v2_meta_box' ); function gc_member_v2_meta_box_html( $post ) { wp_nonce_field( 'gc_member_v2_save', 'gc_member_v2_nonce' ); $fields = array( 'gc_member_bio' => __( 'Bio', 'game-changers' ), 'gc_member_profession' => __( 'Profession', 'game-changers' ), 'gc_member_organisation' => __( 'Organisation', 'game-changers' ), 'gc_member_job_title' => __( 'Job Title', 'game-changers' ), 'gc_member_skills' => __( 'Skills (comma separated)', 'game-changers' ), 'gc_member_leadership_focus' => __( 'Leadership Focus (comma separated)', 'game-changers' ), ); foreach ( $fields as $key => $label ) { $value = get_post_meta( $post->ID, $key, true ); $tag = 'gc_member_bio' === $key ? 'textarea' : 'input'; echo '<p><label for="' . esc_attr( $key ) . '"><strong>' . esc_html( $label ) . '</strong></label><br>'; if ( 'textarea' === $tag ) { echo '<textarea id="' . esc_attr( $key ) . '" name="' . esc_attr( $key ) . '" rows="4" style="width:100%;">' . esc_textarea( $value ) . '</textarea>'; } else { echo '<input type="text" id="' . esc_attr( $key ) . '" name="' . esc_attr( $key ) . '" value="' . esc_attr( $value ) . '" style="width:100%;">'; } echo '</p>'; } echo '<p><label><strong>' . esc_html__( 'Chapter ID', 'game-changers' ) . '</strong></label><br><input type="number" min="0" name="gc_member_chapter_id" value="' . esc_attr( get_post_meta( $post->ID, 'gc_member_chapter_id', true ) ) . '" style="width:100%;"></p>'; echo '<p><label><strong>' . esc_html__( 'Cohort ID', 'game-changers' ) . '</strong></label><br><input type="number" min="0" name="gc_member_cohort_id" value="' . esc_attr( get_post_meta( $post->ID, 'gc_member_cohort_id', true ) ) . '" style="width:100%;"></p>'; $public = get_post_meta( $post->ID, 'gc_member_public_profile', true ); echo '<p><label><input type="checkbox" name="gc_member_public_profile" value="1" ' . checked( $public, 1, false ) . '> ' . esc_html__( 'Allow public member profile', 'game-changers' ) . '</label></p>'; } function gc_platform_meta_box( $post_type, $id, $title, $fields ) { $GLOBALS['gc_platform_meta_fields'][ $post_type ] = isset( $GLOBALS['gc_platform_meta_fields'][ $post_type ] ) ? $GLOBALS['gc_platform_meta_fields'][ $post_type ] : array(); $GLOBALS['gc_platform_meta_fields'][ $post_type ] = array_merge( $GLOBALS['gc_platform_meta_fields'][ $post_type ], $fields ); add_meta_box( $id, $title, function( $post ) use ( $fields ) { wp_nonce_field( 'gc_platform_meta_save', 'gc_platform_meta_nonce' ); foreach ( $fields as $key => $field ) { $value = get_post_meta( $post->ID, $key, true ); $type = isset( $field['type'] ) ? $field['type'] : 'text'; echo '<p><label for="' . esc_attr( $key ) . '"><strong>' . esc_html( $field['label'] ) . '</strong></label><br>'; if ( 'textarea' === $type ) { echo '<textarea id="' . esc_attr( $key ) . '" name="' . esc_attr( $key ) . '" rows="4" style="width:100%;">' . esc_textarea( $value ) . '</textarea>'; } else { echo '<input type="' . esc_attr( $type ) . '" id="' . esc_attr( $key ) . '" name="' . esc_attr( $key ) . '" value="' . esc_attr( $value ) . '" style="width:100%;">'; } echo '</p>'; } }, $post_type, 'normal', 'default' ); } function gc_save_platform_meta( $post_id ) { $post_type = get_post_type( $post_id ); $registry = isset( $GLOBALS['gc_platform_meta_fields'][ $post_type ] ) ? $GLOBALS['gc_platform_meta_fields'][ $post_type ] : array(); if ( empty( $registry ) ) { return; } if ( ! isset( $_POST['gc_platform_meta_nonce'] ) || ! wp_verify_nonce( $_POST['gc_platform_meta_nonce'], 'gc_platform_meta_save' ) ) { return; } if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) { return; } if ( ! current_user_can( 'edit_post', $post_id ) ) { return; } foreach ( $registry as $key => $field ) { if ( ! isset( $_POST[ $key ] ) ) { continue; } $type = isset( $field['type'] ) ? $field['type'] : 'text'; $value = wp_unslash( $_POST[ $key ] ); if ( 'url' === $type ) { $value = esc_url_raw( $value ); } elseif ( 'number' === $type ) { $value = absint( $value ); } elseif ( 'textarea' === $type ) { $value = sanitize_textarea_field( $value ); } else { $value = sanitize_text_field( $value ); } update_post_meta( $post_id, $key, $value ); } } add_action( 'save_post', 'gc_save_platform_meta' );

